import { Fragment, type CSSProperties, type ReactNode } from 'react';

/**
 * A small TSX highlighter for the generated playground code, with the colors of the
 * site's code blocks (GitHub light and dark, as `--shiki-*` variables). The code it
 * colors is generated by the playground, so a regular expression is enough.
 */
const TOKEN =
  /(\/\/[^\n]*)|('(?:[^'\\\n]|\\.)*'|"(?:[^"\\\n]|\\.)*"|`(?:[^`\\]|\\.)*`)|(<\/?)([A-Za-z][\w.]*)|\b(import|from|export|default|function|const|return|type|as)\b|\b(true|false|null|undefined|\d+)\b|([A-Za-z_$][\w$]*)(?==[^=>])|([A-Za-z_$][\w$]*)(?=[(<]\s*[\w'"(]?)/g;

const COLORS = {
  comment: ['#6A737D', '#6A737D'],
  string: ['#032F62', '#9ECBFF'],
  keyword: ['#D73A49', '#F97583'],
  constant: ['#005CC5', '#79B8FF'],
  component: ['#005CC5', '#79B8FF'],
  element: ['#22863A', '#85E89D'],
  attribute: ['#6F42C1', '#B392F0'],
  function: ['#6F42C1', '#B392F0'],
} as const;

const colored = (kind: keyof typeof COLORS, text: string, key: number) => (
  <span
    key={key}
    style={
      {
        '--shiki-light': COLORS[kind][0],
        '--shiki-dark': COLORS[kind][1],
      } as CSSProperties
    }
  >
    {text}
  </span>
);

function highlightLine(line: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  let last = 0;
  let key = 0;
  for (const match of line.matchAll(TOKEN)) {
    const [
      text,
      comment,
      string,
      bracket,
      tag,
      keyword,
      constant,
      attribute,
      call,
    ] = match;
    if (match.index > last) nodes.push(line.slice(last, match.index));
    if (comment) nodes.push(colored('comment', text, key++));
    else if (string) nodes.push(colored('string', text, key++));
    else if (tag) {
      // `useState<string>` is a type argument, `<div` an element.
      const isType = /[\w$]/.test(line[match.index - 1] ?? '');
      nodes.push(bracket);
      nodes.push(
        colored(
          isType || /^[A-Z]/.test(tag) ? 'component' : 'element',
          tag,
          key++,
        ),
      );
    } else if (keyword) nodes.push(colored('keyword', text, key++));
    else if (constant) nodes.push(colored('constant', text, key++));
    else if (attribute) nodes.push(colored('attribute', text, key++));
    else if (call) nodes.push(colored('function', text, key++));
    else nodes.push(text);
    last = match.index + text.length;
  }
  if (last < line.length) nodes.push(line.slice(last));
  return nodes;
}

/** Lines as `<span>`s, the markup the site's code blocks use. */
export function highlightTsx(code: string): ReactNode {
  return code.split('\n').map((line, i) => (
    <Fragment key={i}>
      {/* The lines are grid rows: an empty one needs a space. */}
      <span>{line ? highlightLine(line) : ' '}</span>
      {'\n'}
    </Fragment>
  ));
}
